// План specs/gps-workflow.md 2.1–2.2 (кейс .qa/tests/gps-workflow/GW-04). PROD, gps (компания «בדיקה»), EN.
// @prod-safe: только просмотр /assessments. Сметы из GPS Workflow (данные QA 02.11 / 12.11): EST-0001…EST-0003.
import { test, expect } from '../../fixtures';
import { ROLE, prepare } from './gps-helpers';

const ESTIMATES: Array<[string, string]> = [
  ['EST-0001', 'QA-John Miller'],
  ['EST-0002', 'QA-Multi D'],
  ['EST-0003', 'QA-Multi C'],
];

test.describe('Estimates — колонка Customer у смет из GPS Workflow (#de10b1)', () => {
  for (const device of ['@desktop', '@android']) {
    test(`Estimates list: Customer column is filled for estimates created from GPS Workflow #de10b1 ${device} @prod-safe`, async ({ asUser }) => {
      test.setTimeout(90_000);
      const page = await asUser(ROLE);
      await prepare(page);
      await page.goto('/assessments');
      await expect(page.getByRole('heading', { name: 'Estimates', level: 1 })).toBeVisible({ timeout: 30_000 });

      const headers = page.getByRole('columnheader');
      await expect(headers.filter({ hasText: 'Customer' })).toHaveCount(1);
      const names = (await headers.allInnerTexts()).map((t) => t.trim());
      const customerIdx = names.indexOf('Customer');
      expect(customerIdx, 'колонка Customer').toBeGreaterThanOrEqual(0);

      for (const [number, customer] of ESTIMATES) {
        const row = page.getByRole('row').filter({ has: page.getByRole('cell', { name: number, exact: true }) });
        await expect(row, `строка ${number}`).toHaveCount(1, { timeout: 30_000 });
        const cell = row.getByRole('cell').nth(customerIdx);
        await expect(cell, `${number}: Customer не пустой`).not.toHaveText(/^\s*$/);
        await expect(cell, `${number}: Customer = ${customer}`).toHaveText(customer);
      }
    });
  }
});
